```python
#!/usr/bin/env python3
import json
import csv
import argparse
from pathlib import Path

def get_field(obj, field_path):
    # dot-separated path, supports lists with numeric index or '*' to join
    parts = field_path.split('.')
    cur = obj
    out = None
    for p in parts:
        if cur is None:
            return ''
        if p == '*':
            if isinstance(cur, list):
                cur = [json.dumps(x, ensure_ascii=False) if not isinstance(x, str) else x for x in cur]
                cur = ' | '.join(map(str, cur))
            else:
                cur = ''
        elif p.isdigit():
            idx = int(p)
            cur = cur[idx] if isinstance(cur, list) and 0 <= idx < len(cur) else ''
        else:
            if isinstance(cur, dict):
                cur = cur.get(p, '')
            else:
                return ''
    if isinstance(cur, (dict, list)):
        return json.dumps(cur, ensure_ascii=False)
    return str(cur)

def extract_annotation_info(task, annotator_index=0):
    # convenience extractor for first annotation result choices & note/email
    annotations = task.get('annotations', [])
    if not annotations:
        return ('', '', '')
    ann = annotations[annotator_index] if annotator_index < len(annotations) else annotations[0]
    email = ann.get('completed_by', {}).get('email', '')
    # find choice value and any textarea note
    choice = ''
    note = ''
    for r in ann.get('result', []):
        if r.get('type') == 'choices':
            choices = r.get('value', {}).get('choices', [])
            choice = choices[0] if choices else ''
        if r.get('type') == 'textarea':
            txt = r.get('value', {}).get('text', [])
            note = ' '.join(txt) if isinstance(txt, list) else str(txt)
    return (email, choice, note)

def main():
    p = argparse.ArgumentParser(description='Convert JSON array to TSV (UTF-8).')
    p.add_argument('json_in', help='Input JSON file (array of tasks)')
    p.add_argument('tsv_out', help='Output TSV file path')
    p.add_argument('--ls-base', default='https://app.heartex.com/projects/{project}/data/task?tab=562999&task={id}',
                   help='Label Studio URL template (must contain {project} and {id})')
    p.add_argument('--fields', nargs='+', default=['record_id','question'],
                   help='Dot paths to include as columns (examples below)')
    p.add_argument('--include-annotations', action='store_true',
                   help='Include up to 3 annotators columns (email,choice,note) automatically')
    args = p.parse_args()

    data = json.load(open(args.json_in, 'r', encoding='utf-8'))

    # header from fields
    header = []
    for f in args.fields:
        header.append(f)
    header.append('LS_url')
    if args.include_annotations:
        for i in range(1,4):
            header += [f'annotator{i}_email', f'annotator{i}_choice', f'annotator{i}_note']

    out_path = Path(args.tsv_out)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    with out_path.open('w', encoding='utf-8', newline='') as fh:
        writer = csv.writer(fh, delimiter='\t', lineterminator='\n')
        writer.writerow(header)
        for task in data:
            row = []
            for f in args.fields:
                if f == 'record_id':
                    row.append(task.get('data', {}).get('record_id', task.get('id', '')))
                else:
                    row.append(get_field(task, f))
            # build LS url using project and id (safe fallback)
            project = task.get('project', '')
            tid = task.get('id', '')
            try:
                ls_url = args.ls_base.format(project=project, id=tid)
            except Exception:
                ls_url = f'{args.ls_base}'
            row.append(ls_url)
            if args.include_annotations:
                for i in range(3):
                    email, choice, note = extract_annotation_info(task, annotator_index=i)
                    row += [email, choice, note]
            writer.writerow(row)

if __name__ == '__main__':
    main()
