import json, csv, argparse, sys
from pathlib import Path

TARGET_ANNOTATORS = [
    ("annotator1", "daniellehuy@gmail.com"),
    ("annotator2", "atar_a@webiks.com"),
    ("annotator3", "eyal_r@webiks.com"),
]

def get_field(obj, path):
    if not path:
        return None
    parts = path.split(".")
    cur = obj
    for p in parts:
        if cur is None:
            return None
        if p == "*":
            return cur
        if p.isdigit():
            idx = int(p)
            try:
                cur = cur[idx]
            except Exception:
                return None
        else:
            if isinstance(cur, dict):
                cur = cur.get(p)
            else:
                return None
    return cur

def normalise(v):
    if v is None:
        return "N/A"
    if isinstance(v, str) and v.strip() == "":
        return "N/A"
    return v

def extract_annotator_by_email(task, email):
    anns = task.get("annotations", []) or []
    for ann in anns:
        cb = ann.get("completed_by") or {}
        if cb.get("email") == email:
            # find first choice (if any) and first textarea (if any)
            choice = None
            note_parts = []
            for r in ann.get("result", []) or []:
                typ = r.get("type")
                if typ == "choices" or r.get("value", {}).get("choices"):
                    vals = r.get("value", {}).get("choices") or []
                    if vals:
                        choice = vals[0]
                elif typ == "textarea" or r.get("value", {}).get("text"):
                    txt = r.get("value", {}).get("text")
                    if txt:
                        note_parts.append(txt)
            note = " ".join(note_parts) if note_parts else None
            return cb.get("email"), choice, note
    return None, None, None

def build_ls_url(template, project, tid):
    try:
        return template.format(project=project, id=tid)
    except Exception:
        return "N/A"

def main():
    p = argparse.ArgumentParser(description="Convert LabelStudio JSON -> TSV with fixed annotator emails")
    p.add_argument("json_in", help="Input JSON file (Label Studio tasks array)")
    p.add_argument("tsv_out", help="Output TSV file")
    p.add_argument("--ls-base", default="https://app.heartex.com/projects/{project}/data/task?tab=562999&task={id}", help="LS URL template")
    p.add_argument("--fields", nargs="+", default=["data.record_id","data.question","data.level"], help="Dot-path fields to include")
    args = p.parse_args()

    js = json.load(open(args.json_in, "r", encoding="utf-8"))
    if isinstance(js, dict) and "tasks" in js:
        tasks = js["tasks"]
    elif isinstance(js, list):
        tasks = js
    else:
        tasks = js.get("tasks", []) if isinstance(js, dict) else []

    header = args.fields[:] + ["LS_url"]
    for key, email in TARGET_ANNOTATORS:
        header += [f"{key}_email", f"{key}_choice", f"{key}_note"]

