    out_path.parent.mkdir(parents=True, exist_ok=True)

    with open(out_path, "w", encoding="utf-8", newline="") as fh:
        w = csv.writer(fh, delimiter="\t")
        w.writerow(header)
        for t in tasks:
            row = []
            for f in args.fields:
                row.append(normalise(get_field(t, f)))
            # LS url
            project = get_field(t, "project") or get_field(t, "project_id") or get_field(t, "projectId")
            tid = get_field(t, "id") or get_field(t, "task_id") or get_field(t, "pk")
            row.append(normalise(build_ls_url(args.ls_base, project, tid)))
            # annotators by email
            for key, email in TARGET_ANNOTATORS:
                a_email, a_choice, a_note = extract_annotator_by_email(t, email)
                row.append(normalise(a_email))
                row.append(normalise(a_choice))
                row.append(normalise(a_note))
            w.writerow(row)

